
import type { BundleComponentInput } from './BundleComponentInput.js';
import type { CategoryReferenceInput } from './CategoryReferenceInput.js';
import type { ImageInput } from './ImageInput.js';
import type { MoneyValueInput } from './MoneyValueInput.js';

export type BundleInput = { "available_for_sale"?: never; "barcode"?: string; "bundle_id"?: never; "categories"?: Array<CategoryReferenceInput>; /** Number of components in the bundle. List responses omit `components`, so use this to show a bundle's size. Format: int32. */ "component_count"?: never; "components"?: Array<BundleComponentInput>; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "delivery_configuration_status"?: never; "description"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "images": Array<ImageInput>; /** Flint line-item tax category. */ "line_item_tax_category"?: "general" | "physical_goods" | "digital_goods" | "software" | "saas" | "services" | "professional_services" | "food" | "prepared_food" | "clothing" | "medical_goods" | "admission"; "merchant_id"?: never; "metadata"?: Record<string, string>; "modifier_set"?: never; /** Attached modifier set. Send null on update to remove it. pattern: ^ms_[0-9A-HJKMNP-TV-Z]{26}$. */ "modifier_set_id": string | null; "name": string; "sku"?: string; "status": "active" | "inactive" | "archived"; "taxable"?: boolean; "unit_price_money": MoneyValueInput; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version"?: never; };
